#include "sc6_service.hpp"
#include <fstream>
#include <unistd.h>
namespace uwb_imu_pl::research {
namespace {using Clock=std::chrono::steady_clock;double ms(Clock::time_point a){return std::chrono::duration<double,std::milli>(Clock::now()-a).count();}
RawInclusionParameters params(const IntegrityConfig& cfg,const YAML::Node& law){RawInclusionParameters p;p.initial_sigmas=cfg.realtime.prior_sigmas;p.numeric.valid=true;p.accel_adc=law["raw_accel_sigma_mps2"].as<double>();p.gyro_adc=law["raw_gyro_sigma_radps"].as<double>();p.accel_rw=cfg.imu.accelerometer_bias_rw_sigma;p.gyro_rw=cfg.imu.gyroscope_bias_rw_sigma;p.gravity=cfg.imu.gravity_mps2;return p;}}
Sc6Service::Sc6Service(const YAML::Node& law,const IntegrityConfig& cfg,const NavigationState& initial,const Eigen::Vector3d& lever,const Sc6MotionDomain& domain,const ImuMeasurement& first,bool tight,bool shadow,bool optimized):config_(cfg),lever_(lever),policy_(resolveRollingPolicy(law,config_)),optimized_(optimized),event_(policy_.budget),proof_(policy_,initial,cfg.realtime.prior_sigmas,cfg.imu.accelerometer_bias_rw_sigma,cfg.imu.gyroscope_bias_rw_sigma,lever,domain.acceleration,domain.rate,tight,optimized),faults_(initial,params(cfg,law),policy_.budget,policy_.max_fault_records,domain.acceleration,domain.rate),recovery_(initial,policy_,tight,optimized),backend_(config_,lever){
 if(shadow)shadow_=std::make_unique<RollingIntegrity>(policy_,initial,cfg.realtime.prior_sigmas,cfg.imu.accelerometer_bias_rw_sigma,cfg.imu.gyroscope_bias_rw_sigma,lever,domain.acceleration,domain.rate);
 if(!policy_.open)throw std::invalid_argument("SC6_REQUIRES_OPEN_EVENT");backend_.initialize(initial,cfg.realtime.prior_sigmas);backend_.ingestImu(first);faults_.append(first);replay_.push_back(first);capsules_.push_back(proof_.certificate().separator);
}
Sc6Result Sc6Service::step(const Sc6Envelope& input,bool fde){
 if(!input.source_valid || input.imu.size()!=10 || input.epoch!=input.uwb.id.value())throw std::invalid_argument("SC6_ARRIVED_SOURCE_UNQUALIFIED");
 Sc6Result result;result.epoch=input.epoch;auto allocation=event_.block(input.epoch);auto start=Clock::now();
 result.alarm_time=Clock::time_point{};size_t old_alerts=faults_.records().size();for(const auto& m:input.imu){backend_.ingestImu(m);faults_.append(m);if(faults_.records().size()>old_alerts){result.alarm_time=Clock::now();old_alerts=faults_.records().size();}replay_.push_back(m);}while(replay_.size()>size_t(10*policy_.replay+1))replay_.pop_front();
 auto tx=backend_.prepareEpoch(input.uwb);result.prepare_ms=ms(start);start=Clock::now();
 auto view=faults_.view();result.action=recovery_.prepare(tx,view,replay_,capsules_,config_,fde);if(result.action.uwb_alarm_time!=Clock::time_point{} && (result.alarm_time==Clock::time_point{} || result.action.uwb_alarm_time<result.alarm_time))result.alarm_time=result.action.uwb_alarm_time;result.candidate_ms=ms(start);result.selected_time=Clock::now();start=Clock::now();
 RollingBoundaryProposalV1 old_proposal;if(shadow_)old_proposal=shadow_->propose(tx,result.action.plan,input.range,view);auto proposal=proof_.propose(tx,result.action.plan,input.range,view);auto capsule=proposal.current;faults_.appendRanges(tx.uwb_batch,capsule,lever_);result.proof_ms=ms(start);start=Clock::now();
 EpochTransaction saved;if(optimized_){saved.id=tx.id;saved.base_graph_version=tx.base_graph_version;saved.imu_group.id=tx.imu_group.id;saved.generic_bridge_group.id=tx.generic_bridge_group.id;saved.generic_bias_continuity_group.id=tx.generic_bias_continuity_group.id;}else saved=tx;auto count=backend_.backendUpdateCount();auto receipt=result.action.current_bridge?backend_.commitEpochRollingResearchV1(std::move(tx),result.action.plan):backend_.commitEpoch(std::move(tx),result.action.plan);result.commit_ms=ms(start);result.commit_time=Clock::now();start=Clock::now();
 result.state=backend_.currentState();result.tag=proof_.committedTag(result.state);auto keys=backend_.retainedKeysV1();if(receipt.backend_updates!=1 || backend_.backendUpdateCount()!=count+1)throw std::runtime_error("SC6_SINGLE_COMMIT");
 result.bound=proof_.finalize(std::move(proposal),receipt,keys,result.state);if(shadow_){auto old=shadow_->finalize(std::move(old_proposal),receipt,keys,result.state);result.old_hpl=old.hpl;result.old_vpl=old.pl.z();}recovery_.committed(result.action,saved,receipt,backend_.factorLedger());saved=EpochTransaction{};proposal=RollingBoundaryProposalV1{};
 capsules_.push_back(capsule);while(capsules_.size()>size_t(policy_.replay+1))capsules_.pop_front();
 auto audit=backend_.onlineMaterialAuditV1();const auto& cert=proof_.certificate();result.version=receipt.graph_version;result.generation=cert.generation;result.parent=cert.parent;result.boundary=cert.separator.epoch;result.source_prefix=cert.source_prefix;result.alerts=faults_.records().size();result.slots=audit.factor_slots;result.live=audit.active_factors;result.ledger=audit.ledger_entries;result.replay=replay_.size();result.capsules=capsules_.size();result.x0=std::find(keys.begin(),keys.end(),gtsam::Symbol('x',0))!=keys.end();result.bias_width=capsule.bias[0].upper()-capsule.bias[0].lower();result.q=allocation.q;result.shared_q=event_.adcRadius((input.epoch-1)*10);
 for(int j=0;j<3;++j){result.tag_width[j]=result.bound.high(j)-result.bound.low(j);result.velocity_width[j]=capsule.v[j].upper()-capsule.v[j].lower();for(int h=0;h<3;++h)result.rotation_width[j]=std::max(result.rotation_width[j],capsule.rotation[j][h].upper()-capsule.rotation[j][h].lower());}for(int j=0;j<6;++j)result.bias_widths[j]=capsule.bias[j].upper()-capsule.bias[j].lower();result.proof_time=Clock::now();
 size_t virt=0,res=0;std::ifstream("/proc/self/statm")>>virt>>res;result.rss=res*size_t(sysconf(_SC_PAGESIZE))/1024;result.action.removed_boundary.clear();result.cleanup_ms=ms(start);return result;
}
}
